sql.where:
AND a.severity = 'CAUTION'

    AND p.site_id = #{siteId}


    AND a.triggered_at >= #{fromAt}


    AND a.triggered_at < #{toAt}


    AND EXISTS (
        SELECT 1
        FROM user_site us
        WHERE us.user_id = #{userId}
          AND us.site_id = p.site_id
          AND us.deleted_at IS NULL
    )

mapper.sql:
p.deleted_at IS NULL
AND s.deleted_at IS NULL

    AND p.site_id = #{siteId}


    AND EXISTS (
        SELECT 1
        FROM user_site us
        WHERE us.user_id = #{userId}
          AND us.site_id = p.site_id
          AND us.deleted_at IS NULL
    )

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM site
    WHERE site_id = #{siteId}
)

SELECT EXISTS(
    SELECT 1
    FROM user_site
    WHERE user_id = #{userId}
      AND site_id = #{siteId}
      AND deleted_at IS NULL
)

SELECT COUNT(DISTINCT c.circuit_id) AS total_circuit_count, COUNT(DISTINCT CASE WHEN ai.result_id IS NOT NULL THEN c.circuit_id END) AS diagnosed_circuit_count FROM circuit c INNER JOIN panel p ON p.panel_id = c.panel_id INNER JOIN site s ON s.site_id = p.site_id LEFT JOIN ai_diagnosis_result ai ON ai.circuit_id = c.circuit_id
AND ai.diagnosed_at >= #{fromAt}
AND ai.diagnosed_at < #{toAt}
WHERE

SELECT COUNT(DISTINCT p.panel_id) AS total_panel_count, COUNT(DISTINCT CASE WHEN r.inspection_id IS NOT NULL THEN p.panel_id END) AS inspected_panel_count, COUNT(r.inspection_id) AS total_inspection_count FROM panel p INNER JOIN site s ON s.site_id = p.site_id LEFT JOIN inspection_result r ON r.panel_id = p.panel_id
AND r.inspected_at >= #{fromAt}
AND r.inspected_at < #{toAt}
WHERE

SELECT p.panel_id, p.name AS panel_name, r.inspected_at, u.name AS inspector_name FROM inspection_result r INNER JOIN panel p ON p.panel_id = r.panel_id INNER JOIN site s ON s.site_id = p.site_id LEFT JOIN `user` u ON u.user_id = r.inspector_id WHERE
AND r.inspected_at >= #{fromAt}
AND r.inspected_at < #{toAt}
ORDER BY r.inspected_at DESC LIMIT #{limit}
